describe('Modal Focus Trap', () => {
    beforeEach(() => {
        cy.visit('/your-modal-page'); // Replace with the actual page URL
        cy.get('#open-modal-button').click(); // Replace with the actual button selector to open the modal
    });

    it('should keep focus inside the modal when tabbing', () => {
        cy.get('#modal').should('be.visible'); // Replace with the actual modal selector
        cy.get('#modal input:first').focus(); // Replace with the actual first focusable element in the modal

        cy.focused().should('have.attr', 'id', 'modal-input-1'); // Replace with the actual ID of the first input
        cy.tab(); // Simulate tabbing
        cy.focused().should('have.attr', 'id', 'modal-input-2'); // Replace with the actual ID of the second input
        cy.tab(); // Simulate tabbing
        cy.focused().should('have.attr', 'id', 'modal-close-button'); // Replace with the actual ID of the close button
        cy.tab(); // Simulate tabbing
        cy.focused().should('have.attr', 'id', 'modal-input-1'); // Should loop back to the first input
    });

    it('should not allow focus to leave the modal', () => {
        cy.get('#modal').should('be.visible'); // Replace with the actual modal selector
        cy.get('body').tab(); // Simulate tabbing from the body
        cy.focused().should('have.attr', 'id', 'modal-input-1'); // Should remain on the first input
    });
});
